pub(crate) fn current_locale(locale: &icu_locale::LanguageIdentifier) -> bool {
    LANGUAGES.binary_search(&locale.language.as_str()).is_ok()
        && locale
            .script
            .is_none_or(|script| SCRIPTS.binary_search(&script.as_str()).is_ok())
        && locale
            .region
            .is_none_or(|region| REGIONS.binary_search(&region.as_str()).is_ok())
        && locale.variants.is_empty()
}
